  const target = graph.length - 1;
  const results = [];

  const dfs = (node, path) => {
    if (node === target) { results.push([...path]); return; } // copy!
    for (const next of graph[node]) {
      path.push(next);
      dfs(next, path);
      path.pop(); // backtrack
    }
  };

