const copyRandomListMap = (head) => {
  if (!head) return null;
  const map = new Map();
  for (let n = head; n; n = n.next) map.set(n, new Node(n.val));
  for (let n = head; n; n = n.next) {
    map.get(n).next = n.next ? map.get(n.next) : null;
    map.get(n).random = n.random ? map.get(n.random) : null;
  }
  return map.get(head);
};

const copyRandomList = (head) => {
  if (!head) return null;

  // 1. weave clones in
  for (let n = head; n; n = n.next.next) n.next = new Node(n.val, n.next);

  // 2. wire randoms using the invariant clone === original.next
  for (let n = head; n; n = n.next.next) {
    n.next.random = n.random ? n.random.next : null;
  }

  // 3. unzip, restoring the original list
  const cloneHead = head.next;
  for (let n = head; n; n = n.next) {
    const clone = n.next;
    n.next = clone.next;
    clone.next = n.next ? n.next.next : null;
  }
  return cloneHead;
};

// build A → B → C with randoms A→C, B→A, C→null
const a = new Node(1), b = new Node(2), c = new Node(3);
a.next = b; b.next = c; a.random = c; b.random = a;
const copy = copyRandomList(a);
console.log(copy.val, copy.next.val, copy.next.next.val);         // 1 2 3
console.log(copy.random.val, copy.next.random.val);                // 3 1
console.log(copy !== a, copy.random !== c);                        // true true (deep copy)
console.log(copyRandomListMap(a).next.random.val);                 // 1
`,f0=`// ============================================================================
// APPROACH: DFS with State (Max So Far)
// ============================================================================
/**
 * INTUITION:
 * We need to traverse the tree (DFS) and keep track of the maximum value we have
 * encountered so far in the current path from the root.
 *
 * For each node:
 * 1. Compare node.val with maxSoFar.
 * 2. If node.val >= maxSoFar, it's a "Good Node". Increment count and update maxSoFar.
 * 3. Continue to children passing the (possibly updated) maxSoFar.
 *
 * Time Complexity: O(N)
 * Space Complexity: O(H)
 */
const goodNodes = (root) => {
  let count = 0;

  const dfs = (node, maxSoFar) => {
    if (!node) return;

    // Check if current node is "Good"
    if (node.val >= maxSoFar) {
      count++;
      maxSoFar = node.val; // Update max for children
    }

    dfs(node.left, maxSoFar);
    dfs(node.right, maxSoFar);
  };

  // Start DFS with root and extremely small initial max
  dfs(root, -Infinity);

  return count;
};

// Definition for a binary tree node
class TreeNode {
  constructor(val = 0, left = null, right = null) {
    this.val = val;
    this.left = left;
    this.right = right;
  }
}

// ============================================================================
// TEST CASES
// ============================================================================
console.log("=== Count Good Nodes Tests ===\\n");

// Case 1: [3,1,4,3,null,1,5]
const tree1 = new TreeNode(
  3,
  new TreeNode(1, new TreeNode(3)),
  new TreeNode(4, new TreeNode(1), new TreeNode(5))
);
console.log("Test 1:", goodNodes(tree1)); // Expected: 4 (3, 3, 4, 5)

module.exports = { goodNodes };
