console.log("=== Jump Game II Tests ===\\n");

console.log("Test 1:", jump([2, 3, 1, 1, 4])); // Expected: 2
console.log("Test 2:", jump([2, 3, 0, 1, 4])); // Expected: 2

module.exports = { jump };
