// APPROACH: Backtracking
// ============================================================================
/**
 * INTUITION:
 * We need to generate combinations where we pick one letter for the first digit,
 * one letter for the second digit, and so on.
 * This is a classic backtracking problem where we explore a decision tree.
 *
 * At each step (index i), we look at the digit \`digits[i]\`.
 * We iterate through all possible letters mapped to that digit.
 * For each letter, we append it to our current string and move to the next digit (i + 1).
 * When our current string length equals the input digits length, we have a valid combination.
 *
 * Time Complexity: O(4^N * N)
 * - In the worst case (digits 7 or 9), each digit has 4 choices.
 * - So there are up to 4^N combinations.
 * - For each combination, we build a string of length N.
 *
 * Space Complexity: O(N)
 * - Recursion stack depth is N (length of digits).
 */
const letterCombinations = (digits) => {
  const res = [];
  // Base case: empty input
  if (digits.length == 0) return res;

  const map = {
    2: "abc",
    3: "def",
    4: "ghi",
    5: "jkl",
    6: "mno",
    7: "pqrs",
    8: "tuv",
    9: "wxyz",
  };

  const backTracking = (index, currStr) => {
    // Base Case: If the current string is the same length as digits, we found a combination
    if (currStr.length === digits.length) {
      res.push(currStr);
      return;
    }

    // Get the letters corresponding to the current digit
    // Loop through each letter and recurse
    for (const c of map[digits[index]]) {
      backTracking(index + 1, currStr + c);
    }
  };

  backTracking(0, "");
  return res;
};

// ============================================================================
// TEST CASES
// ============================================================================
console.log("=== Letter Combinations Tests ===\\n");
console.log("Test 1 ('23'):", letterCombinations("23"));
// Expected: ["ad","ae","af","bd","be","bf","cd","ce","cf"]

console.log("Test 2 (''):", letterCombinations(""));
// Expected: []

console.log("Test 3 ('2'):", letterCombinations("2"));
// Expected: ["a","b","c"]

module.exports = { letterCombinations };
`,bx=`// Definition for a binary tree node
class TreeNode {
  constructor(val = 0, left = null, right = null) {
    this.val = val;
    this.left = left;
    this.right = right;
  }
}

/**
 * @param {TreeNode} root
 * @return {number[][]}
 */
const levelOrderTraversal = (root) => {
  // If tree is empty, return empty result
  if (!root) return [];

  // Final result: array of levels
  const result = [];

  // Queue for BFS — ALWAYS store nodes, never values
  const queue = [root];

  // Run BFS while there are nodes to process
  while (queue.length > 0) {
    // Snapshot of current level size
    const levelSize = queue.length;

    // This array will store values of ONE level
    const currentLevel = [];

    // Process exactly \`levelSize\` nodes
    for (let i = 0; i < levelSize; i++) {
      // Remove node from front of queue
      const node = queue.shift();

      // Store node value in current level
      currentLevel.push(node.val);

      // Add children to queue (for next level)
      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }

    // After finishing this level, save it
    result.push(currentLevel);
  }

  return result;
};

// ============================================================================
// SAMPLE TEST CASES
// ============================================================================

// Helper function to build tree from array (level order)
function buildTree(arr) {
  if (!arr || arr.length === 0 || arr[0] === null) return null;

  const root = new TreeNode(arr[0]);
  const queue = [root];
  let i = 1;

  while (queue.length > 0 && i < arr.length) {
    const node = queue.shift();

    if (i < arr.length && arr[i] !== null) {
      node.left = new TreeNode(arr[i]);
      queue.push(node.left);
    }
    i++;

    if (i < arr.length && arr[i] !== null) {
      node.right = new TreeNode(arr[i]);
      queue.push(node.right);
    }
    i++;
  }

  return root;
}

// Test Case 1:
//         3
//        / \\
//       9  20
//          / \\
//         15  7
const tree1 = buildTree([3, 9, 20, null, null, 15, 7]);
console.log("Test 1:", JSON.stringify(levelOrderTraversal(tree1)));
// Expected: [[3],[9,20],[15,7]]

// Test Case 2: Single node
const tree2 = buildTree([1]);
console.log("Test 2:", JSON.stringify(levelOrderTraversal(tree2)));
// Expected: [[1]]

// Test Case 3: Empty tree
console.log("Test 3:", JSON.stringify(levelOrderTraversal(null)));
// Expected: []

// Test Case 4: Complete binary tree
//           1
//         /   \\
//        2     3
//       / \\   / \\
//      4   5 6   7
const tree4 = buildTree([1, 2, 3, 4, 5, 6, 7]);
console.log("Test 4:", JSON.stringify(levelOrderTraversal(tree4)));
// Expected: [[1],[2,3],[4,5,6,7]]

// Test Case 5: Left-heavy tree
//         1
//        /
//       2
//      /
//     3
const tree5 = buildTree([1, 2, null, 3]);
console.log("Test 5:", JSON.stringify(levelOrderTraversal(tree5)));
// Expected: [[1],[2],[3]]

// Test Case 6: Right-heavy tree
//     1
//      \\
//       2
//        \\
//         3
const tree6 = buildTree([1, null, 2, null, 3]);
console.log("Test 6:", JSON.stringify(levelOrderTraversal(tree6)));
// Expected: [[1],[2],[3]]
