console.log("Test 2:", removeKdigits("10200", 1));   // Expected: "200"
console.log("Test 3:", removeKdigits("10", 2));      // Expected: "0"
console.log("Test 4:", removeKdigits("9", 1));       // Expected: "0"

module.exports = { removeKdigits };
