console.log("Test 1:", singleNonDuplicate([1, 1, 2, 3, 3, 4, 4, 8, 8])); // Expected: 2
console.log("Test 2:", singleNonDuplicate([3, 3, 7, 7, 10, 11, 11])); // Expected: 10
