  // 2️⃣ Min-heap of size k
  const heap = new MinHeap();

  for (let [num, count] of freq.entries()) {
    heap.push([num, count]);
    if (heap.size() > k) {
      heap.pop();
    }
  }

  // 3️⃣ Extract result
  const result = [];
  while (heap.size()) {
    result.push(heap.pop()[0]);
  }

  return result;
