//   [2, 2, 1, -1],
//   [1, -1, 2, -1],
//   [0, -1, 3, 4]
// ]

const test2 = [[INF]];
wallsAndGates(test2);
console.log("\\nTest 2 (Single Empty):", test2);
// Expected: [[2147483647]] (Unreachable)

const test3 = [[0]];
wallsAndGates(test3);
console.log("\\nTest 3 (Single Gate):", test3);
// Expected: [[0]]

module.exports = { wallsAndGates };
